close("tsvd_sv", t.singular_values_, tsvd_sv); close("tsvd_tr", t.transform(X[:4]), tsvd_tr)
t2 = TruncatedSVD(2, algorithm="arpack").fit(X)
close("tsvda_comp", t2.components_, tsvda_comp); close("tsvda_ev", t2.explained_variance_, tsvda_ev)
p = PCA(3, svd_solver="randomized", random_state=1, whiten=True).fit(X)
close("pcar_comp", p.components_, pcar_comp); close("pcar_ev", p.explained_variance_, pcar_ev)
closes("pcar_noise", p.noise_variance_, pcar_noise)
close("pcar_tr", p.transform(X[:3]), pcar_tr); close("pcar_ss", p.score_samples(X[:5]), pcar_ss)
pf = PCA(2, svd_solver="full").fit(X)
close("pcaf_ss", pf.score_samples(X[:5]), pcaf_ss); close("pcaf_inv", pf.inverse_transform(pf.transform(X[:2])), pcaf_inv)

def nmf_cd(init: str, H, W5, err, it):
    m = NMF(3, init=init, random_state=0, max_iter=400)
    W = m.fit_transform(Xp)
    close("nmf_cd_" + init + "_H", m.components_, H, 1e-5, 1e-7); close("nmf_cd_" + init + "_W", W[:5], W5, 1e-5, 1e-7)
    closes("nmf_cd_" + init + "_err", m.reconstruction_err_, err)
    if m.n_iter_ != it:
        print("TEST FAILED nmf iters", init, m.n_iter_, it)
nmf_cd("nndsvd", nmf_cd_nndsvd_H, nmf_cd_nndsvd_W, nmf_cd_nndsvd_err, nmf_cd_nndsvd_it)
nmf_cd("nndsvda", nmf_cd_nndsvda_H, nmf_cd_nndsvda_W, nmf_cd_nndsvda_err, nmf_cd_nndsvda_it)
nmf_cd("nndsvdar", nmf_cd_nndsvdar_H, nmf_cd_nndsvdar_W, nmf_cd_nndsvdar_err, nmf_cd_nndsvdar_it)
nmf_cd("random", nmf_cd_random_H, nmf_cd_random_W, nmf_cd_random_err, nmf_cd_random_it)
m = NMF(3, init="nndsvda", solver="mu", beta_loss="kullback-leibler", random_state=0, max_iter=300)
m.fit_transform(Xp)
close("nmf_kl_H", m.components_, nmf_kl_H, 1e-5, 1e-7); closes("nmf_kl_err", m.reconstruction_err_, nmf_kl_err)
if m.n_iter_ != nmf_kl_it:
    print("TEST FAILED nmf_kl_it", m.n_iter_)
close("nmf_kl_tr", m.transform(Xp[:3]), nmf_kl_tr, 1e-5, 1e-7)
m = NMF(3, init="nndsvd", solver="mu", random_state=0, max_iter=200, alpha_W=0.01, l1_ratio=0.5)
m.fit_transform(Xp)
close("nmf_mu_H", m.components_, nmf_mu_H, 1e-5, 1e-7); closes("nmf_mu_err", m.reconstruction_err_, nmf_mu_err)
m = NMF(2, init="random", solver="cd", random_state=3, shuffle=True, alpha_W=0.02, alpha_H=0.01, l1_ratio=0.3)
