close("nmf_sh_H", m.components_, nmf_sh_H, 1e-5, 1e-7); close("nmf_sh_tr", m.transform(Xp[:3]), nmf_sh_tr, 1e-5, 1e-7)

def kp(k: str, g: Optional[float], inv: bool, eig, Z4, tr):
    kp = KernelPCA(3, kernel=k, gamma=g, fit_inverse_transform=inv)
    Z = kp.fit_transform(X)
    close("kpca_" + k + "_eig", kp.eigenvalues_, eig); close("kpca_" + k + "_Z", Z[:4], Z4)
    close("kpca_" + k + "_tr", kp.transform(X[:3] + 0.1), tr)
    if inv:
        close("kpca_rbf_inv", kp.inverse_transform(Z[:3]), kpca_rbf_inv, 1e-5)
kp("linear", None, False, kpca_linear_eig, kpca_linear_Z, kpca_linear_tr)
kp("poly", 0.1, False, kpca_poly_eig, kpca_poly_Z, kpca_poly_tr)
kp("rbf", 0.1, True, kpca_rbf_eig, kpca_rbf_Z, kpca_rbf_tr)
kp("sigmoid", 0.1, False, kpca_sigmoid_eig, kpca_sigmoid_Z, kpca_sigmoid_tr)
kp("cosine", 0.1, False, kpca_cosine_eig, kpca_cosine_Z, kpca_cosine_tr)

ip = IncrementalPCA(3, batch_size=8).fit(X)
close("ipca_comp", ip.components_, ipca_comp); close("ipca_ev", ip.explained_variance_, ipca_ev)
close("ipca_evr", ip.explained_variance_ratio_, ipca_evr); closes("ipca_noise", ip.noise_variance_, ipca_noise)
close("ipca_var", ip.var_, ipca_var)
fa = FactorAnalysis(2).fit(X)
close_sign("fa_comp", fa.components_, fa_comp, 6, False); close("fa_noise", fa.noise_variance_, fa_noise, 1e-5)
if fa.n_iter_ != fa_it:
    print("TEST FAILED fa_it", fa.n_iter_)
close_sign("fa_tr", fa.transform(X[:3]), fa_tr, 2, True); close("fa_ss", fa.score_samples(X[:4]), fa_ss, 1e-5)
fv = FactorAnalysis(2, rotation="varimax").fit(X)
close_sign("fav_comp", fv.components_, fav_comp, 6, False)
